/**
 * Connector: Typeform form response -> Pipedrive organization, person, deal
 */
export interface ConnectorConfig {
  /** Pipedrive API token (Bearer) */
  pipedriveApiToken: string;
  /** Optional fetch implementation for testing */
  fetch?: typeof fetch;
}

/** Minimal shape of the Typeform webhook payload we care about */
export interface TypeFormPayload {
  event_id: string;
  event_type: string;
  form_response: {
    form_id: string;
    token: string;
    submitted_at: string;
    definition: {
      id: string;
      title: string;
      fields: Array<{
        id: string;
        title: string;
        type: string;
        ref: string;
      }>;
    };
    answers: Array<{
      type: string;
      text?: string;
      email?: string;
      field: {
        id: string;
        type: string;
      };
    }>;
    ending: {
      id: string;
      ref: string;
    };
  };
}

export interface ConnectorResult {
  organizationId: number;
  personId: number;
  dealId: number;
}

/** Extract the relevant answers from the Typeform payload by matching field titles */
function extractFields(payload: TypeFormPayload): {
  name: string | undefined;
  email: string | undefined;
  phone: string | undefined;
  company: string | undefined;
  formTitle: string;
} {
  const { definition, answers } = payload.form_response;
  // Map field title -> field id
  const fieldIdByTitle = new Map<string, string>();
  for (const field of definition.fields) {
    fieldIdByTitle.set(field.title, field.id);
  }

  // Helper to find answer value by field title
  const getAnswer = (title: string): string | undefined => {
    const fieldId = fieldIdByTitle.get(title);
    if (!fieldId) return undefined;
    const answer = answers.find((a) => a.field.id === fieldId);
    if (!answer) return undefined;
    // Value can be in `text` or `email` property
    return answer.text ?? answer.email;
  };

  const name = getAnswer('What is your first name?');
  const email = getAnswer('Please give us your email address.');
  const phone = getAnswer('Phone number');
  const company = getAnswer('Company name');
  const formTitle = definition.title;

  return { name, email, phone, company, formTitle };
}

/** Main entry point */
export async function handle(
  payload: TypeFormPayload,
  config: ConnectorConfig
): Promise<ConnectorResult> {
  const fetchFn = config.fetch ?? fetch;
  const token = config.pipedriveApiToken;

  const { name, email, phone, company, formTitle } = extractFields(payload);

  // Validate required fields
  if (!name) throw new Error('Missing required field: name');
  if (!email) throw new Error('Missing required field: email');
  if (!phone) throw new Error('Missing required field: phone');
  if (!company) throw new Error('Missing required field: company');

  const organizationName = company || name;

  // 1. Create organization
  const orgRes = await fetchFn('https://api.pipedrive.com/v2/organizations', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ name: organizationName }),
  });
  if (!orgRes.ok) {
    throw new Error(
      `Failed to create organization: ${orgRes.status} ${orgRes.statusText} at ${orgRes.url}`
    );
  }
  const orgData = await orgRes.json();
  const organizationId = orgData.data.id as number;

  // 2. Create person linked to organization
  const personRes = await fetchFn('https://api.pipedrive.com/v2/persons', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      name,
      email: [{ value: email, primary: true }],
      phone: [{ value: phone, primary: true }],
      organization_id: organizationId,
    }),
  });
  if (!personRes.ok) {
    throw new Error(
      `Failed to create person: ${personRes.status} ${personRes.statusText} at ${personRes.url}`
    );
  }
  const personData = await personRes.json();
  const personId = personData.data.id as number;

  // 3. Create deal linked to person
  const dealTitle = formTitle || 'Contact Form Submission';
  const dealRes = await fetchFn('https://api.pipedrive.com/v2/deals', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      title: dealTitle,
      person_id: personId,
      value: 0,
      status: 'open',
    }),
  });
  if (!dealRes.ok) {
    throw new Error(
      `Failed to create deal: ${dealRes.status} ${dealRes.statusText} at ${dealRes.url}`
    );
  }
  const dealData = await dealRes.json();
  const dealId = dealData.data.id as number;

  return { organizationId, personId, dealId };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, TypeFormPayload } from './connector';
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures';

// Helper to build a valid test payload (based on SOURCE_EXAMPLE) with optional overrides
function createTestPayload(overrides: Partial<{
  name: string | undefined;
  email: string | undefined;
  phone: string | undefined;
  company: string | undefined;
}> = {}): TypeFormPayload {
  const base = JSON.parse(JSON.stringify(SOURCE_EXAMPLE)) as TypeFormPayload;
  const { definition, answers } = base.form_response;
  const fieldIdByTitle = new Map<string, string>();
  for (const field of definition.fields) {
    fieldIdByTitle.set(field.title, field.id);
  }
  const setAnswer = (title: string, value: string | undefined) => {
    const fieldId = fieldIdByTitle.get(title);
    if (!fieldId) return;
    const answer = answers.find((a) => a.field.id === fieldId);
    if (!answer) return;
    if (value === undefined) {
      // Remove the answer by setting a non-matching field id? Instead we'll just delete the answer from array.
      const idx = answers.indexOf(answer);
      if (idx !== -1) answers.splice(idx, 1);
    } else {
      if (answer.type === 'email') {
        answer.email = value;
      } else {
        answer.text = value;
      }
    }
  };
  if (overrides.name !== undefined) setAnswer('What is your first name?', overrides.name);
  if (overrides.email !== undefined) setAnswer('Please give us your email address.', overrides.email);
  if (overrides.phone !== undefined) setAnswer('Phone number', overrides.phone);
  if (overrides.company !== undefined) setAnswer('Company name', overrides.company);
  return base;
}

// Contract test (must be at top level with title 'contract')
describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      pipedriveApiToken: 'test-token',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeFormPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    // The documented responses have fixed ids
    expect(result.organizationId).toBe(123);
    expect(result.personId).toBe(456);
    expect(result.dealId).toBe(789);
  });
});

describe('handle', () => {
  it('creates organization, person, and deal with correct field mapping', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ success: true, data: { id: 1, name: 'Acme Corp' } }, 201);
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ success: true, data: { id: 2, name: 'John Doe', organization_id: 1 } }, 201);
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ success: true, data: { id: 3, title: 'Contact Form', person_id: 2 } }, 201);
      }
      return jsonResponse({ error: 'Not found' }, 404);
    });

    const payload = createTestPayload();
    const config: ConnectorConfig = { pipedriveApiToken: 'token', fetch };
    const result = await handle(payload, config);

    expect(result).toEqual({ organizationId: 1, personId: 2, dealId: 3 });
    expect(calls.length).toBe(3);

    // Organization creation
    expect(calls[0].json).toEqual({ name: 'Acme Corp' });
    expect(calls[0].headers.get('authorization')).toBe('Bearer token');

    // Person creation
    expect(calls[1].json).toEqual({
      name: 'John Doe',
      email: [{ value: 'john.doe@example.com', primary: true }],
      phone: [{ value: '+1234567890', primary: true }],
      organization_id: 1,
    });
    expect(calls[1].headers.get('authorization')).toBe('Bearer token');

    // Deal creation
    expect(calls[2].json).toEqual({
      title: 'Contact Form',
      person_id: 2,
      value: 0,
      status: 'open',
    });
    expect(calls[2].headers.get('authorization')).toBe('Bearer token');
  });

  it('throws when required field name is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = createTestPayload({ name: undefined });
    const config: ConnectorConfig = { pipedriveApiToken: 'token', fetch };
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: name');
  });

  it('throws when required field email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = createTestPayload({ email: undefined });
    const config: ConnectorConfig = { pipedriveApiToken: 'token', fetch };
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email');
  });

  it('throws when required field phone is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = createTestPayload({ phone: undefined });
    const config: ConnectorConfig = { pipedriveApiToken: 'token', fetch };
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: phone');
  });

  it('throws when required field company is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = createTestPayload({ company: undefined });
    const config: ConnectorConfig = { pipedriveApiToken: 'token', fetch };
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: company');
  });

  it('throws on non-2xx response from Pipedrive', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ error: 'Unauthorized' }, 401);
      }
      return jsonResponse({}, 200);
    });
    const payload = createTestPayload();
    const config: ConnectorConfig = { pipedriveApiToken: 'token', fetch };
    await expect(handle(payload, config)).rejects.toThrow(
      'Failed to create organization: 401 Unauthorized at https://api.pipedrive.com/v2/organizations'
    );
    expect(calls.length).toBe(1);
  });
});

# Typeform to Pipedrive Connector

This connector receives a Typeform webhook payload (form response submitted) and creates three linked records in Pipedrive:
1. An **Organization** (using the company name from the form)
2. A **Person** linked to that organization (using name, email, phone from the form)
3. A **Deal** linked to that person (using the form title as deal name)

## Configuration

The connector requires the following environment variable / config property:

| Config key | Environment variable | Description |
|------------|----------------------|-------------|
| `pipedriveApiToken` | `PIPEDRIVE_API_TOKEN` | Pipedrive API personal token (Bearer authentication) |

The connector accepts an optional `fetch` implementation in the config for testing (defaults to global `fetch`).

## Usage Example

```typescript
import { handle, ConnectorConfig, TypeFormPayload } from './connector';

// Example webhook handler (e.g., in a serverless function)
export async function webhookHandler(request: Request) {
  const payload = (await request.json()) as TypeFormPayload;
  const config: ConnectorConfig = {
    pipedriveApiToken: process.env.PIPEDRIVE_API_TOKEN!,
  };
  try {
    const result = await handle(payload, config);
    return new Response(JSON.stringify({ success: true, ...result }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (err) {
    console.error(err);
    return new Response(JSON.stringify({ success: false, error: String(err) }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    });
  }
}
```

## Assumptions

- The Typeform webhook payload includes fields for **name**, **email**, **phone**, and **company** (matched by the field titles in the form definition).
- The form definition titles are exactly:
  - "What is your first name?" → name
  - "Please give us your email address." → email
  - "Phone number" → phone
  - "Company name" → company
- Pipedrive API requires separate calls to create an organization, then a person linked to that organization, then a deal linked to that person.
- The user has a valid Pipedrive API token with permissions to create organizations, persons, and deals.
- The deal value is set to `0` and status to `open` by default.
- No authentication is performed on the incoming Typeform webhook (security relies on HTTPS and optionally a shared secret, not covered here).

## Error Handling

- Missing required fields in the Typeform payload throw a descriptive `Error`.
- Non-2xx responses from Pipedrive throw an `Error` including the HTTP status code and the endpoint URL.

