export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://api.pipedrive.com/v2/organizations",
    "response": {
      "success": true,
      "data": {
        "id": 123,
        "name": "Acme Corp",
        "add_time": "2025-04-05T12:34:56Z",
        "update_time": "2025-04-05T12:34:56Z"
      }
    }
  },
  {
    "method": "POST",
    "url": "https://api.pipedrive.com/v2/persons",
    "response": {
      "success": true,
      "data": {
        "id": 456,
        "name": "John Doe",
        "email": [
          {
            "value": "john.doe@example.com",
            "primary": true
          }
        ],
        "phone": [
          {
