// Helper to build a valid test payload (based on SOURCE_EXAMPLE) with optional overrides
function createTestPayload(overrides: Partial<{
  name: string | undefined;
  email: string | undefined;
  phone: string | undefined;
  company: string | undefined;
}> = {}): TypeFormPayload {
  // Deep clone the example
  const base = JSON.parse(JSON.stringify(SOURCE_EXAMPLE)) as TypeFormPayload;
  const formResponse = base.form_response;
  const definition = formResponse.definition;
  const answers = formResponse.answers;

  // Build field title -> field id map from definition
  const fieldIdByTitle = new Map<string, string>();
  for (const field of definition.fields) {
    if (field.title && field.id) {
      fieldIdByTitle.set(field.title, field.id);
    }
  }

  const setAnswer = (title: string, value: string | undefined) => {
    const fieldId = fieldIdByTitle.get(title);
    if (!fieldId) return;
    const answerIndex = answers.findIndex((a) => a.field?.id === fieldId);
    if (answerIndex === -1) return;
    if (value === undefined) {
      answers.splice(answerIndex, 1);
    } else {
      const answer = answers[answerIndex];
      if (answer.type === 'email') {
        answer.email = value;
      } else {
        answer.text = value;
      }
    }
  };

  if (overrides.name !== undefined) setAnswer('What is your first name?', overrides.name);
  if (overrides.email !== undefined) setAnswer('Please give us your email address.', overrides.email);
  if (overrides.phone !== undefined) setAnswer('Phone number', overrides.phone);
  if (overrides.company !== undefined) setAnswer('Company name', overrides.company);

  return base;
}

