        return jsonResponse({ success: true, data: { id: 2, name: 'John Doe', organization_id: 1 } }, 201);
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ success: true, data: { id: 3, title: 'Contact Form', person_id: 2 } }, 201);
      }
      return jsonResponse({ error: 'Not found' }, 404);
    });

    const payload = createTestPayload();
    const config: ConnectorConfig = { pipedriveApiToken: 'token', fetch };
    const result = await handle(payload, config);

    expect(result).toEqual({ organizationId: 1, personId: 2, dealId: 3 });
    expect(calls.length).toBe(3);

    // Organization creation
    expect(calls[0].json).toEqual({ name: 'Acme Corp' });
    expect(calls[0].headers.get('authorization')).toBe('Bearer token');

    // Person creation
    expect(calls[1].json).toEqual({
      name: 'John Doe',
      email: [{ value: 'john.doe@example.com', primary: true }],
      phone: [{ value: '+1234567890', primary: true }],
      organization_id: 1,
    });
    expect(calls[1].headers.get('authorization')).toBe('Bearer token');

    // Deal creation
    expect(calls[2].json).toEqual({
      title: 'Contact Form',
      person_id: 2,
      value: 0,
      status: 'open',
    });
    expect(calls[2].headers.get('authorization')).toBe('Bearer token');
  });

  it('throws when required field name is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = createTestPayload({ name: undefined });
    const config: ConnectorConfig = { pipedriveApiToken: 'token', fetch };
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: name');
  });

  it('throws when required field email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = createTestPayload({ email: undefined });
    const config: ConnectorConfig = { pipedriveApiToken: 'token', fetch };
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email');
  });

  it('throws when required field phone is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = createTestPayload({ phone: undefined });
    const config: ConnectorConfig = { pipedriveApiToken: 'token', fetch };
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: phone');
  });

  it('throws when required field company is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = createTestPayload({ company: undefined });
    const config: ConnectorConfig = { pipedriveApiToken: 'token', fetch };
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: company');
  });

  it('throws on non-2xx response from Pipedrive', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ error: 'Unauthorized' }, 401);
      }
      return jsonResponse({}, 200);
    });
    const payload = createTestPayload();
    const config: ConnectorConfig = { pipedriveApiToken: 'token', fetch };
    await expect(handle(payload, config)).rejects.toThrow(
      'Failed to create organization: 401 Unauthorized at https://api.pipedrive.com/v2/organizations'
    );
    expect(calls.length).toBe(1);
  });
});

# Typeform to Pipedrive Connector

This connector receives a Typeform webhook payload (form response submitted) and creates three linked records in Pipedrive:
1. An **Organization** (using the company name from the form)
2. A **Person** linked to that organization (using name, email, phone from the form)
3. A **Deal** linked to that person (using the form title as deal name)

## Configuration

The connector requires the following environment variable / config property:

| Config key | Environment variable | Description |
|------------|----------------------|-------------|
| `pipedriveApiToken` | `PIPEDRIVE_API_TOKEN` | Pipedrive API personal token (Bearer authentication) |

The connector accepts an optional `fetch` implementation in the config for testing (defaults to global `fetch`).

## Usage Example

```typescript
import { handle, ConnectorConfig, TypeFormPayload } from './connector';

// Example webhook handler (e.g., in a serverless function)
export async function webhookHandler(request: Request) {
  const payload = (await request.json()) as TypeFormPayload;
  const config: ConnectorConfig = {
    pipedriveApiToken: process.env.PIPEDRIVE_API_TOKEN!,
  };
  try {
    const result = await handle(payload, config);
    return new Response(JSON.stringify({ success: true, ...result }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (err) {
    console.error(err);
    return new Response(JSON.stringify({ success: false, error: String(err) }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    });
  }
}
```

## Assumptions

- The Typeform webhook payload includes fields for **name**, **email**, **phone**, and **company** (matched by the field titles in the form definition).
- The form definition titles are exactly:
  - "What is your first name?" → name
  - "Please give us your email address." → email
  - "Phone number" → phone
  - "Company name" → company
- Pipedrive API requires separate calls to create an organization, then a person linked to that organization, then a deal linked to that person.
- The user has a valid Pipedrive API token with permissions to create organizations, persons, and deals.
- The deal value is set to `0` and status to `open` by default.
- No authentication is performed on the incoming Typeform webhook (security relies on HTTPS and optionally a shared secret, not covered here).

## Error Handling

- Missing required fields in the Typeform payload throw a descriptive `Error`.
- Non-2xx responses from Pipedrive throw an `Error` including the HTTP status code and the endpoint URL.

